import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import { XMLParser } from 'fast-xml-parser';
import { Upload, FileText, CheckCircle, AlertCircle } from 'lucide-react';
import './App.css';

function App() {
  const [xmlContent, setXmlContent] = useState('');
  const [parsedResult, setParsedResult] = useState(null);
  const [error, setError] = useState(null);

  // 1. Configuration for the XML Parser
  const parser = new XMLParser({
    ignoreAttributes: false,
    attributeNamePrefix: "@_"
  });

  // 2. Validation and Extraction Logic
  const processXML = (xmlString) => {
    try {
      setError(null);
      setParsedResult(null);

      const jsonObj = parser.parse(xmlString);

      // Helper to find specific value deep in object
      // NOTE: In real ISO20022, structure is Document -> pacs.008 -> GrpHdr etc.
      const doc = jsonObj.Document || jsonObj; 

      let type = 'Unknown';
      let isValid = false;
      let extractedData = [];
      let validationMessage = '';

      // LOGIC FOR 008 (SCT Inst / pacs.008)
      if (xmlString.includes('pacs.008') || xmlString.includes('CustomerCreditTransferInitiation')) {
        type = 'SCT Inst (008)';

        // Example Validation: Check if Group Header exists
        const header = doc?.["urn:iso:std:iso:20022:tech:xsd:pacs.008.001.08"]?.CustomerCreditTransferInitiation?.GrpHdr ||
                       doc?.CustomerCreditTransferInitiation?.GrpHdr; // Fallback for non-namespaced XML

        if (header) {
            isValid = true;
            validationMessage = "Structure matches SCT Inst (008)";
            extractedData = [
                { label: 'Message ID', value: header.MsgId },
                { label: 'Creation Date', value: header.CreDtTm },
                { label: 'Nb of Tx', value: header.NbOfTxs },
                { label: 'Settlement Method', value: header.SttlmInf?.SttlmMtd || 'N/A' }
            ];
        } else {
            validationMessage = "Invalid 008: Missing Group Header";
        }
      } 

      // LOGIC FOR 002 (Status Report / pain.002)
      else if (xmlString.includes('pain.002') || xmlString.includes('CustomerPaymentStatusReport')) {
        type = 'Status Report (002)';

        const header = doc?.["urn:iso:std:iso:20022:tech:xsd:pain.002.001.10"]?.CustomerPaymentStatusReport?.GrpHdr ||
                       doc?.CustomerPaymentStatusReport?.GrpHdr;

        if (header) {
            isValid = true;
            validationMessage = "Structure matches Status Report (002)";
            extractedData = [
                { label: 'Message ID', value: header.MsgId },
                { label: 'Creation Date', value: header.CreDtTm },
                { label: 'Initiating Party', value: header.InitgPty?.Nm || 'N/A' }
            ];
        } else {
             validationMessage = "Invalid 002: Missing Group Header";
        }
      } else {
          validationMessage = "Unknown XML Type. Could not identify 008 or 002 signatures.";
      }

      setParsedResult({
        type,
        isValid,
        message: validationMessage,
        data: extractedData
      });

    } catch (err) {
      setError("Failed to parse XML. Please check syntax.");
      console.error(err);
    }
  };

  // 3. Handle File Drop
  const onDrop = useCallback((acceptedFiles) => {
    const file = acceptedFiles[0];
    const reader = new FileReader();

    reader.onabort = () => setError('File reading was aborted');
    reader.onerror = () => setError('File reading has failed');
    reader.onload = () => {
      const binaryStr = reader.result;
      setXmlContent(binaryStr);
      processXML(binaryStr);
    };
    reader.readAsText(file);
  }, []);

  const { getRootProps, getInputProps } = useDropzone({ 
    onDrop, 
    accept: {'text/xml': ['.xml'], 'application/xml': ['.xml']} 
  });

  // 4. Handle Manual Paste
  const handleManualPaste = () => {
    if (!xmlContent) return;
    processXML(xmlContent);
  };

  return (
    <div className="container">
      <div className="header">
        <h1>SCT Inst Validator (008 & 002)</h1>
        <p>Upload or Paste your XML to validate structure and extract values.</p>
      </div>

      <div className="input-methods">
        {/* Drag and Drop Section */}
        <div className="card">
            <h3><Upload size={20} style={{marginRight:'8px', verticalAlign:'bottom'}}/> Upload File</h3>
            <div {...getRootProps({ className: 'dropzone' })}>
                <input {...getInputProps()} />
                <p>Drag & drop XML file here, or click to select</p>
            </div>
        </div>

        {/* Copy Paste Section */}
        <div className="card">
            <h3><FileText size={20} style={{marginRight:'8px', verticalAlign:'bottom'}}/> Copy / Paste</h3>
            <textarea 
                placeholder="Paste XML content here..." 
                value={xmlContent}
                onChange={(e) => setXmlContent(e.target.value)}
            />
            <button className="btn" onClick={handleManualPaste}>Validate XML</button>
        </div>
      </div>

      {/* Error Display */}
      {error && (
          <div className="card" style={{borderColor: '#dc3545', color: '#dc3545'}}>
              <AlertCircle size={20} style={{verticalAlign: 'bottom'}}/> {error}
          </div>
      )}

      {/* Results Display */}
      {parsedResult && !error && (
        <div className="results-area card">
            <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                <h2>Analysis Results</h2>
                <span className={`badge ${parsedResult.isValid ? 'badge-success' : 'badge-error'}`}>
                    {parsedResult.isValid ? 'VALID' : 'INVALID'}
                </span>
            </div>

            <div style={{marginTop: '15px'}}>
                <strong>Detected Type: </strong> <span className="badge badge-info">{parsedResult.type}</span>
            </div>

            <p>{parsedResult.message}</p>

            {parsedResult.data.length > 0 && (
                <>
                <h3>Extracted Values</h3>
                <table>
                    <thead>
                        <tr>
                            <th>Field Name</th>
                            <th>Extracted Value</th>
                        </tr>
                    </thead>
                    <tbody>
                        {parsedResult.data.map((row, index) => (
                            <tr key={index}>
                                <td>{row.label}</td>
                                <td><code>{row.value}</code></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                </>
            )}
        </div>
      )}
    </div>
  );
}

export default App;
